import java.time.LocalDateTime
import java.time.format.DateTimeFormatter

/*
 * This file was generated by the Gradle 'init' task.
 *
 * This project uses @Incubating APIs which are subject to change.
 */

plugins {
    `java-library`
    `maven-publish`
}

repositories {
    mavenLocal()
    maven {
        url = uri("https://repo.maven.apache.org/maven2/")
    }
}

group = "org.example"
version = "1.0-SNAPSHOT"
description = "Project.Module2"
java.sourceCompatibility = JavaVersion.VERSION_1_8

publishing {
    publications.create<MavenPublication>("maven") {
        from(components["java"])
    }
}

tasks.withType<JavaCompile>() {
    options.encoding = "UTF-8"
}

tasks.withType<Javadoc>() {
    options.encoding = "UTF-8"
}

val generateBuildInfo = tasks.register("generateBuildInfo"){
    val currentDate = LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"))
    val outputFile = layout.projectDirectory.file("build-info.txt")
    val  projectVersion = project.version.toString()

    doLast{
        outputFile.asFile.writeText("Version: $projectVersion\nBuild Date: $currentDate")
    }
}

tasks.named("build") {
    dependsOn("generateBuildInfo")
}
